<?php
use App\Services\Money;
$typeLabels = ['opening' => 'Saldo awal', 'damage' => 'Kerusakan', 'correction' => 'Koreksi', 'reversal' => 'Pembalik'];
$statusLabels = ['draft' => 'Draft', 'submitted' => 'Menunggu persetujuan owner', 'approved' => 'Disetujui, siap diposting', 'rejected' => 'Perlu perbaikan', 'posted' => 'Sudah diposting', 'cancelled' => 'Dibatalkan'];
$money = static fn (mixed $value): string => ($value < 0 ? '-Rp' : 'Rp') . number_format(abs((float) $value), 2, ',', '.');
$rows = array_map(static function (array $line) use ($money): array {
    $quantityMilli = Money::quantityMilli($line['quantity_delta']);
    $quantity = ($quantityMilli > 0 ? '+' : '') . panel_qty($line['quantity_delta']) . ' ' . esc($line['base_unit']);
    return ['<strong>' . esc($line['item_name']) . '</strong><span class="block text-xs text-ink-muted">' . esc($line['sku']) . '</span>', $quantity, 'Rp' . number_format((float) $line['unit_cost'], 4, ',', '.'), $money($line['value_delta'])];
}, $lines);
$url = 'panel/inventory/adjustments/' . (int) $adjustment['id'];
?>
<nav class="mb-6 text-sm" aria-label="Breadcrumb"><a class="font-bold underline decoration-brand-sun decoration-2 underline-offset-4 focus-ring" href="<?= site_url('panel/inventory/adjustments') ?>">Kembali ke daftar penyesuaian</a></nav>
<header class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="section-kicker"><?= esc($typeLabels[$adjustment['adjustment_type']] ?? 'Penyesuaian stok') ?></p><h1 class="mt-2 break-words font-display text-3xl leading-tight sm:text-4xl"><?= esc($adjustment['reference_number']) ?></h1><p class="mt-3 text-ink-muted"><?= esc(date('d/m/Y', strtotime($adjustment['document_date']))) ?> · dibuat oleh <?= esc($adjustment['creator_name']) ?></p></div><p><span class="status-label bg-surface-soft-yellow text-ink-muted"><?= esc($statusLabels[$adjustment['status']] ?? 'Status tidak dikenal') ?></span></p></header>
<section class="panel-card mb-6 p-5 sm:p-6" aria-label="Ringkasan penyesuaian"><p class="text-sm font-bold text-ink-muted">Alasan dan sumber</p><p class="mt-2 whitespace-pre-line leading-6"><?= esc($adjustment['reason']) ?></p><?php if ($adjustment['offset_account_name']): ?><p class="mt-3 text-sm"><span class="text-ink-muted">Akun lawan saldo awal:</span> <strong><?= esc($adjustment['offset_account_code'] . ' · ' . $adjustment['offset_account_name']) ?></strong></p><?php endif ?><?php if ($adjustment['original_reference']): ?><p class="mt-3 text-sm">Membalik dokumen <a class="font-bold underline focus-ring" href="<?= site_url('panel/inventory/adjustments/' . $adjustment['reversal_of_id']) ?>"><?= esc($adjustment['original_reference']) ?></a></p><?php elseif ($adjustment['reversal_reference']): ?><p class="mt-3 text-sm">Sudah dibalik oleh <a class="font-bold underline focus-ring" href="<?= site_url('panel/inventory/adjustments/' . $adjustment['reversal_id']) ?>"><?= esc($adjustment['reversal_reference']) ?></a></p><?php endif ?>
    <dl class="mt-4 grid gap-x-6 gap-y-2 border-t border-border-warm pt-4 text-sm sm:grid-cols-2"><div><dt class="text-ink-muted">Diajukan oleh</dt><dd class="font-semibold"><?= esc($adjustment['submitter_name'] ?: 'Belum diajukan') ?><?= $adjustment['submitted_at'] ? ' · ' . esc(date('d/m/Y H:i', strtotime($adjustment['submitted_at']))) : '' ?></dd></div><?php if ($adjustment['reviewed_by']): ?><div><dt class="text-ink-muted">Ditinjau oleh</dt><dd class="font-semibold"><?= esc($adjustment['reviewer_name']) ?> · <?= esc(date('d/m/Y H:i', strtotime($adjustment['reviewed_at']))) ?></dd></div><?php endif ?><?php if ($adjustment['posted_by']): ?><div><dt class="text-ink-muted">Diposting oleh</dt><dd class="font-semibold"><?= esc($adjustment['poster_name']) ?> · <?= esc(date('d/m/Y H:i', strtotime($adjustment['posted_at']))) ?></dd></div><?php endif ?></dl>
    <?php if ($adjustment['review_notes']): ?><div class="mt-4 border border-status-warning bg-[#FFFCF4] p-4 text-sm"><h2 class="font-bold">Catatan owner</h2><p class="mt-1 whitespace-pre-line leading-6"><?= esc($adjustment['review_notes']) ?></p></div><?php endif ?>
</section>
<?= panel_table('Rincian perubahan stok', ['Bahan', '>Perubahan jumlah', '>Biaya per satuan', '>Perubahan nilai'], $rows, ['search' => false, 'width' => '42rem', 'empty' => 'Belum ada bahan pada dokumen ini.']) ?>
<?php if ($canEdit): ?>
<section class="panel-card mb-8 p-5 sm:p-6"><h2 class="font-bold">Tambah atau perbarui bahan</h2><p class="mt-1 text-sm text-ink-muted"><?php if ($adjustment['adjustment_type'] === 'damage'): ?>Masukkan jumlah rusak sebagai angka positif; sistem mengurangi stok dan memakai biaya rata-rata saat pengajuan.<?php elseif ($adjustment['adjustment_type'] === 'correction'): ?>Gunakan jumlah positif untuk stok bertambah dan negatif untuk stok berkurang. Biaya diperlukan untuk penambahan.<?php else: ?>Masukkan saldo awal positif dan biaya per satuan. Bahan harus belum memiliki saldo stok.<?php endif ?></p>
