    <div class="mt-5 flex flex-col gap-3 border-t border-border-warm pt-5 sm:flex-row sm:items-center sm:justify-between"><p class="text-sm text-ink-muted"><?= count($lines) ?> bahan · stok belum berubah</p><?php if ($lines === []): ?><button class="button-primary cursor-not-allowed opacity-50" type="button" disabled aria-disabled="true">Ajukan ke owner</button><?php else: ?><?= panel_post($url . '/submit', [], 'Ajukan ke owner', 'button-primary', 'Ajukan penyesuaian untuk diperiksa owner? Stok dan jurnal belum berubah.') ?><?php endif ?></div>
</section>
<?php endif ?>
