<?php if ($canPost): ?><section class="panel-card mb-8 flex flex-col gap-3 border-brand-cocoa p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6"><div><h2 class="font-bold">Siap diposting</h2><p class="mt-1 text-sm text-ink-muted">Posting mengubah saldo bahan, kartu stok, dan jurnal secara bersamaan. Perubahan stok setelah persetujuan akan membuat posting ditolak.</p></div><?= panel_post('panel/inventory/adjustments/post', ['adjustment_id' => $adjustment['id']], 'Posting penyesuaian', 'button-primary shrink-0', 'Posting penyesuaian ini ke stok dan jurnal?') ?></section><?php endif ?>
<?php if ($canReverse): ?><section class="panel-card mb-8 border-status-danger p-5 sm:p-6"><h2 class="font-bold">Buat dokumen pembalik</h2><p class="mt-1 text-sm text-ink-muted">Transaksi asal tetap tersimpan. Pembalik akan mencatat jumlah dan jurnal kebalikan sebagai transaksi baru; tindakan ini hanya dapat dilakukan sekali.</p><form action="<?= site_url($url . '/reverse') ?>" method="post" class="mt-4 grid gap-4 sm:grid-cols-[1fr_auto] sm:items-end" data-confirm-form="Buat dan posting dokumen pembalik? Transaksi asal akan tetap tersimpan."><?= csrf_field() ?><div><label class="form-label" for="reversal-reason">Alasan pembalik</label><textarea class="form-input min-h-20" id="reversal-reason" name="reason" minlength="5" maxlength="500" required></textarea></div><button class="button-secondary" type="submit">Balik transaksi</button></form></section><?php endif ?>
